import os
import glob
import json
from stages.cctf_utils import decode_cctf_frames, migrate_record_schema

def process_scanner_file(file_path, config):
    frames = decode_cctf_frames(file_path)
    pending = []
    savepoints = {}
    committed = []

    for ver, ftype, seq, payload_bytes in frames:
        if ftype == 1:  # TXN
            try:
                record = json.loads(payload_bytes.decode("utf-8"))
            except Exception:
                continue
            record = migrate_record_schema(ver, record, config)
            pending.append(record)
        elif ftype == 5:  # SAVEPOINT
            try:
                data = json.loads(payload_bytes.decode("utf-8"))
                sp_name = data.get("savepoint")
                if sp_name:
                    savepoints[sp_name] = len(pending)
            except Exception:
                pass
        elif ftype == 6:  # ROLLBACK
            try:
                data = json.loads(payload_bytes.decode("utf-8"))
                sp_name = data.get("savepoint")
                if sp_name and sp_name in savepoints:
                    target_idx = savepoints[sp_name]
                    pending = pending[:target_idx]
                    savepoints = {k: v for k, v in savepoints.items() if v <= target_idx}
            except Exception:
                pass
        elif ftype == 3:  # COMMIT
            committed.extend(pending)
            pending = []
            savepoints = {}
        elif ftype == 4:  # ABORT
            pending = []
            savepoints = {}

    return committed

def recover_ledgers(data_dir: str, output_dir: str, config: dict = None) -> dict:
    """
    Recovers scanner transaction ledgers from data_dir.
    Handles partial writes (truncated CCTF files) and atomic-rename gaps.
    Writes recovered files to output_dir and returns audit dictionary.
    """
    if config is None:
        config_path = os.path.join(os.path.dirname(os.path.dirname(__file__)), "config", "pipeline_config.json")
        if os.path.exists(config_path):
            with open(config_path, "r", encoding="utf-8") as f:
                config = json.load(f)
        else:
            config = {}

    os.makedirs(output_dir, exist_ok=True)

    # Find all scanner files
    scanner_ids = set()
    for fname in os.listdir(data_dir):
        if fname.startswith("scanner_"):
            if fname.endswith(".cctf.tmp"):
                sid = fname[len("scanner_") : -len(".cctf.tmp")]
                scanner_ids.add(sid)
            elif fname.endswith(".cctf"):
                sid = fname[len("scanner_") : -len(".cctf")]
                scanner_ids.add(sid)

    audit_recovery = {}

    for sid in sorted(scanner_ids):
        main_file = os.path.join(data_dir, f"scanner_{sid}.cctf")
        tmp_file = os.path.join(data_dir, f"scanner_{sid}.cctf.tmp")

        recs_main = process_scanner_file(main_file, config) if os.path.exists(main_file) else []
        recs_tmp = process_scanner_file(tmp_file, config) if os.path.exists(tmp_file) else []

        # Merge deduplicated: keep higher timestamp on duplicate transaction_id
        tx_map = {}
        for r in recs_main + recs_tmp:
            tx_id = r.get("transaction_id")
            if not tx_id:
                continue
            if tx_id not in tx_map:
                tx_map[tx_id] = r
            else:
                if r.get("timestamp", 0) > tx_map[tx_id].get("timestamp", 0):
                    tx_map[tx_id] = r

        merged_records = list(tx_map.values())
        merged_records.sort(key=lambda x: (x.get("sequence", 0), x.get("timestamp", 0), x.get("transaction_id", "")))

        out_file = os.path.join(output_dir, f"recovered_{sid}.json")
        with open(out_file, "w", encoding="utf-8") as f:
            json.dump(merged_records, f, indent=2)

        audit_recovery[sid] = len(merged_records)

    audit_file = os.path.join(output_dir, "audit_recovery.json")
    with open(audit_file, "w", encoding="utf-8") as f:
        json.dump(audit_recovery, f, indent=2)

    return audit_recovery
